mapper.select:
SELECT FINPROD_ID AS code, FINPROD_NAME AS name, FINPROD_ABBR AS shortName, FINPROD_TYPE AS hidCode FROM FIN_PRODUCT FP WHERE 1=1 and FP.FINPROD_TYPE2 not in ('F01','F06','F10')
AND FP.FINPROD_TYPE = #{finprodType}
AND FP.FINPROD_TYPE IN ('F01','F06','F07','F17','F16','F21','F26') /** modify by yanya on 20200106 增加通道类型 F26 **/

SELECT FCI.CASH_ID AS code, FCI.CASH_TYPE_2 AS name, FCI.CASH_TYPE_2 AS hidCode FROM FIN_CASH_INFO FCI INNER JOIN BOK_BOOKSET BST ON FCI.FINPROD_ID = BST.ACCT_SUBJECT_ID
WHERE FCI.CASH_TYPE_2 IN ('C03','C04','C05','C06','C07','C09','C10') AND BST.BOOKSET_ID = #{booksetId}
AND FCI.CASH_TYPE_2 = #{finprodType}

SELECT BASE_SUBJECT_NATURE
FROM BOK_SUBJECT_NATURE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT distinct T.code,T.hidCode FROM ( SELECT BALI.LAYERING_ID AS code, BALI.BUSI_DETAIL_TYPE AS hidCode FROM BOK_ACCT_LAYERING_INFO BALI WHERE BALI.BRANCH = #{branch}
UNION ALL
SELECT FTP.FINPROD_ID AS code, FTP.FINPROD_TYPE AS hidCode FROM FIN_TRADE_PRODUCT FTP WHERE FTP.BRANCH = #{branch}
UNION ALL
SELECT BCI.ACCT_NO AS code, BCI.ACCT_TYPE AS hidCode FROM BOK_BOOKSET_CAPACCT_INFO BCI WHERE BCI.BOOKSET_ID = #{booksetId} ) T WHERE T.CODE = #{finprodId}

    	SELECT
		    FP.FINPROD_ID AS id,
		    FP.BRANCH AS text
		FROM FIN_TRADE_PRODUCT FP
		WHERE 1=1
		/** ADN FP.FINPROD_TYPE IN ('F01','F17') AND FP.BRANCH_TYPE IN ('D01','D02') **/
		AND FP.FINPROD_TYPE = #{finprodType}

			AND FP.BRANCH_TYPE = #{branchType}

		AND FP.FINPROD_ID = #{finprodId}

SELECT A.LAYERING_ID AS code, A.LAYERING_NAME AS name, A.LAYERING_NAME AS shortName, A.BUSI_DETAIL_TYPE AS linkValue, A.BUSI_DETAIL_TYPE AS hidCode FROM BOK_ACCT_LAYERING_INFO A WHERE A.BOOKSET_ID = #{booksetId}
AND A.BUSI_DETAIL_TYPE IN
#{finprodType}

SELECT ACCT_NO FROM BOK_BOOKSET_CAPACCT_INFO 
WHERE BOOKSET_ID = #{booksetId}
AND ACCT_TYPE = #{acctType}
AND CCY = #{ccy}

SELECT FP.FINPROD_ID AS code, FP.FINPROD_NAME AS name, FP.FINPROD_ABBR AS shortName, FP.FINPROD_TYPE AS hidCode FROM FIN_PRODUCT FP left join fin_product_add fpd on fp.finprod_id = fpd.finprod_id WHERE 1=1 and FP.FINPROD_TYPE2 in ('F01','F06','F10') and fpd.appear_market_id is null
AND FP.FINPROD_TYPE = #{finprodType}
AND FP.FINPROD_TYPE IN ('F01','F06','F07','F17','F16','F21','F26') /** modify by yanya on 20200106 增加通道类型 F26 **/
